import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import {
  AllCommunityModule,
  ColDef,
  ColGroupDef,
  Column,
  ColumnResizedEvent,
  GridReadyEvent,
  ModuleRegistry,
  RowHeightParams,
} from 'ag-grid-community';
import { AgGridReact, AgGridReactProps } from 'ag-grid-react';
import { FilterValue } from 'models/Filters';

import { CustomNoRows } from './components';
import { getRowClass, getRowHeight, onColumnResized } from './config/callbacks';
import { createGridOptions } from './config/columnDefs';
import { ROW_HEIGHT_EMPTY } from './constants';
import { CustomStyleDefault, StyledTableContainer } from './Table.styles';
import { AgGridTheme } from './theme';
import { TableChartType, TableDataType, TableRowType } from './types';
import { getAllFields, getAllFieldsToHide } from './utils';
import { generateColumnDefs } from './utils/generateColumnDefs';
import { generateRowData } from './utils/generateRowData';

ModuleRegistry.registerModules([AllCommunityModule]);

const SCROLLBAR_OVERFLOW_HYSTERESIS_PX = 4;

export type ColumnDefConfig =
  | (Omit<ColDef, 'headerTooltip'> & {
      headerTooltip?: string | React.ReactNode;
    })
  | (Omit<ColGroupDef, 'headerTooltip'> & {
      headerTooltip?: string | React.ReactNode;
    });

export type ColumnDefsConfig = Record<string, ColumnDefConfig>;

export type TableFilter = {
  allFieldsToFilter: FilterValue[];
  fieldsToHide: FilterValue[];
};

export type EmptyRow = {
  addOnStart?: boolean;
  addOnEnd?: boolean;
};

export type NoRowsMessage = {
  title?: string;
  description?: string;
};

type TableStyleWrapperProps = {
  children?: React.ReactNode;
};

interface TableProps {
  data: TableDataType;
  style?: React.ComponentType<TableStyleWrapperProps>;
  fixedHeight?: string;
  columnDefsConfig?: ColumnDefsConfig;
  chartType?: TableChartType;
  rowHeight?: number;
  headerHeight?: number;
  groupHeaderHeight?: number;
  scrollbarWidth?: number;
  emptyRow?: EmptyRow;
  separatorBetweenGroups?: boolean;
  autoHeight?: boolean;
  filter?: TableFilter;
  noRowsMessage?: NoRowsMessage;
  dataTestId?: string;
  /** When true, column widths come from columnDefs only (no auto-size / size-to-fit). */
  manageColumnWidths?: boolean;

  onGridReadyCallback?: (params: GridReadyEvent) => void;
  getRowHeightCallback?: (params: RowHeightParams) => number;
}

export const Table: React.FC<TableProps & AgGridReactProps> = ({
  data,
  style,
  fixedHeight,
  columnDefsConfig,
  chartType,
  rowHeight = 48,
  headerHeight = 56,
  groupHeaderHeight = 56,
  scrollbarWidth = 48,
  emptyRow,
  separatorBetweenGroups = true,
  autoHeight = false,
  filter,
  noRowsMessage,
  dataTestId,
  manageColumnWidths = false,
  onGridReadyCallback,
  getRowHeightCallback,
  ...rest
}) => {
  const [gridApi, setGridApi] = useState(null);
  const gridApiRef = useRef<GridReadyEvent['api'] | null>(null);
  const containerRef = useRef(null);
  const scrollbarReservedRef = useRef(false);
  const gridReadyFitTimerRef = useRef<ReturnType<typeof setTimeout>>();
  const [height, setHeight] = useState(fixedHeight ?? 'auto');

  const setHeightIfChanged = useCallback((nextHeight: string) => {
    setHeight((currentHeight) =>
      currentHeight === nextHeight ? currentHeight : nextHeight,
    );
  }, []);

  const CustomStyle = style || CustomStyleDefault;

  const resolvedGridOptions = useMemo(
    () =>
      createGridOptions(
        manageColumnWidths ? { autoSizeStrategy: undefined } : undefined,
      ),
    [manageColumnWidths],
  );

  const columnDefs = useMemo(() => {
    return data.header ? generateColumnDefs(data.header, columnDefsConfig) : [];
  }, [data.header, columnDefsConfig]);

  const allFields = useMemo(() => {
    if (!gridApi) return [];
    const columnDefs = gridApi?.getColumnDefs();
    return getAllFields(columnDefs);
  }, [gridApi]);

  const fieldsToHideMemoized = useMemo(
    () => getAllFieldsToHide(filter),
    [filter],
  );

  const rowData = useMemo(() => {
    return data.rows
      ? generateRowData(
          data.rows,
          chartType,
          emptyRow?.addOnStart,
          emptyRow?.addOnEnd,
          separatorBetweenGroups,
        )
      : [];
  }, [
    data.rows,
    chartType,
    emptyRow?.addOnEnd,
    emptyRow?.addOnStart,
    separatorBetweenGroups,
  ]);

  const calculateTotalHeight = useCallback(() => {
    if (autoHeight || fixedHeight) {
      if (fixedHeight) {
        setHeightIfChanged(fixedHeight);
      }
      return;
    }

    const containerElement = containerRef.current;
    if (!containerElement || !gridApi) return;

    const headerElement = containerElement.querySelector('.ag-header');
    if (!headerElement) return;

    const headerHeight = headerElement.offsetHeight;
    const headerWidth = headerElement.offsetWidth;
    const headerContentWidth = gridApi
      .getColumns()
      .reduce((total: number, column: Column) => {
        return total + column.getActualWidth();
      }, 0);

    const contentOverflow = headerContentWidth - headerWidth;

    if (manageColumnWidths) {
      scrollbarReservedRef.current =
        contentOverflow > SCROLLBAR_OVERFLOW_HYSTERESIS_PX;
    } else if (contentOverflow > SCROLLBAR_OVERFLOW_HYSTERESIS_PX) {
      // Hysteresis avoids toggling scrollbar reserve when overflow is near the edge.
      scrollbarReservedRef.current = true;
    } else if (contentOverflow < -SCROLLBAR_OVERFLOW_HYSTERESIS_PX) {
      scrollbarReservedRef.current = false;
    }

    const minHeight = scrollbarReservedRef.current
      ? headerHeight + scrollbarWidth
      : headerHeight;

    if (!rowData || rowData.length === 0) {
      setHeightIfChanged('536px');
      return;
    }

    const rowsHeight = rowData.reduce(
      (acc: number, row: TableRowType, index: number) => {
        if (row.isEmpty) return acc + ROW_HEIGHT_EMPTY;

        const node = gridApi?.getRowNode?.(index.toString());
        const realHeight = node?.rowHeight ?? rowHeight;
        return acc + realHeight;
      },
      0,
    );

    setHeightIfChanged(`${Number(rowsHeight) + minHeight}px`);
  }, [
    setHeightIfChanged,
    gridApi,
    rowData,
    autoHeight,
    fixedHeight,
    rowHeight,
    scrollbarWidth,
    manageColumnWidths,
  ]);

  const fitColumnsAndHeight = useCallback(() => {
    if (!gridApiRef.current) return;

    if (!manageColumnWidths) {
      gridApiRef.current.sizeColumnsToFit();
    }

    calculateTotalHeight();
  }, [calculateTotalHeight, manageColumnWidths]);

  const onGridReady = (event: GridReadyEvent) => {
    setGridApi(event.api);
    gridApiRef.current = event.api;

    onGridReadyCallback?.(event);

    if (!autoHeight) {
      if (manageColumnWidths) {
        calculateTotalHeight();
      } else {
        event.api.autoSizeAllColumns();
        clearTimeout(gridReadyFitTimerRef.current);
        gridReadyFitTimerRef.current = setTimeout(() => {
          fitColumnsAndHeight();
        }, 1000);
      }
    }
  };

  const checkVisibility = () => {
    const container = containerRef.current;
    if (!container) return false;

    const rect = container.getBoundingClientRect();
    return (
      rect.top >= 0 &&
      rect.left >= 0 &&
      rect.bottom <=
        (window.innerHeight || document.documentElement.clientHeight) &&
      rect.right <= (window.innerWidth || document.documentElement.clientWidth)
    );
  };

  useLayoutEffect(() => {
    if (autoHeight || manageColumnWidths) return;

    const container = containerRef.current;
    if (!container) return;

    const isVisible = checkVisibility();

    if (isVisible) {
      fitColumnsAndHeight();
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          fitColumnsAndHeight();
        }
      });
    });

    observer.observe(container);

    return () => {
      observer.disconnect();
    };
  }, [autoHeight, manageColumnWidths, containerRef, fitColumnsAndHeight]);

  useEffect(() => {
    if (autoHeight || manageColumnWidths) return;

    const container = containerRef.current;
    if (!container) return;

    const observeTarget = container.parentElement ?? container;
    let resizeTimeout: ReturnType<typeof setTimeout>;
    let lastObservedWidth = observeTarget.clientWidth;

    const scheduleFitColumnsAndHeight = () => {
      clearTimeout(resizeTimeout);
      resizeTimeout = setTimeout(fitColumnsAndHeight, 100);
    };

    const resizeObserver = new ResizeObserver(() => {
      const nextWidth = observeTarget.clientWidth;
      if (nextWidth === lastObservedWidth) return;

      lastObservedWidth = nextWidth;
      scheduleFitColumnsAndHeight();
    });

    resizeObserver.observe(observeTarget);

    return () => {
      clearTimeout(resizeTimeout);
      resizeObserver.disconnect();
    };
  }, [autoHeight, manageColumnWidths, fitColumnsAndHeight]);

  useEffect(() => {
    return () => {
      clearTimeout(gridReadyFitTimerRef.current);
    };
  }, []);

  useEffect(() => {
    if (!gridApi || !filter) return;

    const timer = setTimeout(() => {
      gridApi.setColumnsVisible(allFields, true);
      gridApi.setColumnsVisible(fieldsToHideMemoized, false);

      if (!autoHeight) {
        gridApi.sizeColumnsToFit();
      }
    }, 100);

    return () => {
      clearTimeout(timer);
    };
  }, [autoHeight, fieldsToHideMemoized, filter, allFields, gridApi]);

  useEffect(() => {
    if (!gridApi || autoHeight || !manageColumnWidths) return;

    const recalculateHeight = () => {
      calculateTotalHeight();
    };

    gridApi.addEventListener('gridSizeChanged', recalculateHeight);
    gridApi.addEventListener('columnResized', recalculateHeight);

    return () => {
      gridApi.removeEventListener('gridSizeChanged', recalculateHeight);
      gridApi.removeEventListener('columnResized', recalculateHeight);
    };
  }, [autoHeight, calculateTotalHeight, gridApi, manageColumnWidths]);

  useEffect(() => {
    if (autoHeight) return;

    calculateTotalHeight();
  }, [autoHeight, rowData, calculateTotalHeight]);

  const noRowsOverlayComponent = () => {
    return (
      <CustomNoRows
        title={noRowsMessage?.title}
        description={noRowsMessage?.description}
      />
    );
  };

  return (
    <CustomStyle>
      <StyledTableContainer
        className="table-container"
        style={autoHeight ? undefined : { height }}
        ref={containerRef}
        data-testid={dataTestId ? `table-${dataTestId}` : undefined}
      >
        <AgGridReact
          columnDefs={columnDefs}
          rowData={rowData}
          theme={AgGridTheme}
          domLayout={autoHeight ? 'autoHeight' : undefined}
          onGridReady={onGridReady}
          onColumnResized={(event: ColumnResizedEvent<any, any>) =>
            onColumnResized(event, containerRef)
          }
          onFirstDataRendered={() => {
            if (!autoHeight) {
              fitColumnsAndHeight();
            }
          }}
          gridOptions={resolvedGridOptions}
          getRowHeight={(params: RowHeightParams) =>
            getRowHeight(params, rowHeight, getRowHeightCallback)
          }
          scrollbarWidth={scrollbarWidth}
          getRowClass={getRowClass}
          rowHeight={rowHeight}
          headerHeight={headerHeight}
          groupHeaderHeight={groupHeaderHeight}
          suppressMovableColumns={true}
          suppressRowTransform={true}
          tooltipShowDelay={100}
          noRowsOverlayComponent={noRowsOverlayComponent}
          {...rest}
        />
      </StyledTableContainer>
    </CustomStyle>
  );
};
